// XRFS -- Emscripten FS backend for the OpenXRay wasm port.
//
// Included into the build with --pre-js. At preRun it loads files.json (the
// index generated by tools/web/make_index.py), mounts a lazy filesystem at
// /cop and chdirs there, so the engine's CLocatorAPI sees the whole game
// layout without any packaging step.
//
//  - reads: small files are fetched whole and cached; big files are read in
//    aligned blocks through HTTP Range requests (browser) or positioned
//    reads (node) with a small LRU block cache. Nothing is preloaded.
//  - writes/creations go to an in-memory overlay (logs, user.ltx, saves);
//    index-backed files become writable via copy-on-write.
//  - lookups are case-insensitive (the engine lowercases some paths it
//    builds by hand), but readdir returns the on-disk casing so URLs match.
//
// Configuration (before the module script loads):
//   XRFS_CONFIG = { baseUrl, indexUrl }        // browser (default: cop/, files.json)
//                = { baseDir, indexFile }      // node (dev harness)

var XRFS_CONFIG_DEFAULTS = {
    mountpoint: '/cop',
    baseUrl: 'cop/',
    indexUrl: 'files.json',
    packUrl: 'pack.bin', // startup bundle of small files (make_index.py)
    baseDir: null,   // node only: local dir serving the game layout
    indexFile: null, // node only: path to files.json
    packFile: null,  // node only: path to pack.bin
    smallFileLimit: 8 * 1024 * 1024,
    // Big files (archives) are cached in small blocks: the engine reads lots
    // of tiny files out of the .db archives at random (3417 .thm before the
    // menu), and 1Mb blocks turned each of those into a 1Mb fetch (~625Mb
    // read before the menu). Long reads still go out as one request: missing
    // neighbouring blocks are coalesced up to maxFetchBytes.
    blockSize: 64 * 1024,
    blockCacheBytes: 96 * 1024 * 1024,
    maxFetchBytes: 16 * 1024 * 1024, // also the worker transport's buffer
    // On a miss, fetch at least this much: per-request latency, not bytes, is
    // what small random reads cost (the sounds of an area load as a burst of
    // ~300 small files that sit next to each other in the archives).
    minFetchBytes: 256 * 1024,
    maxSeqFetchBytes: 2 * 1024 * 1024,
    // Small files fetched whole are mostly read once (textures go straight to
    // the GPU), so keep only the recently used ones. Unbounded, a Zaton load
    // pinned ~1.6Gb here on top of the wasm heap.
    smallCacheBytes: 256 * 1024 * 1024,
    // Overlay paths under this prefix (lowercased, relative to the mount)
    // survive page reloads in IndexedDB: saves, user.ltx, screenshots.
    persistPrefix: '_appdata_/',
    // logs; caches (should a build still write one) are regenerated, never worth keeping
    persistSkip: ['_appdata_/logs/', '_appdata_/cdb_cache/', '_appdata_/shaders_cache_oxr/'],
    persistDb: 'xrfs-appdata',
};

var XRFS = {
    DIR_MODE: 0x4000 | 0o777,
    FILE_MODE: 0x8000 | 0o777,

    // Errno codes as seen by the FS layer: this emsdk build uses the WASI
    // numbering (e.g. ENOENT = 44, EACCES = 2), not the musl one. Throwing a
    // musl code here makes the engine print misleading strerror()s and breaks
    // noent_okay suppression in lookupPath.
    E: {
        EPERM: 63, ENOENT: 44, EIO: 29, EEXIST: 20, ENODEV: 43,
        EINVAL: 28, ENOMEM: 48, EISDIR: 31, ENOTDIR: 54,
    },

    cfg: null,
    index: null,   // tree: { dirs: { lower: [origName, subtree] }, files: { lower: [origName, size, mtime] } }
    overlay: null, // Map: path -> { type:'dir' } | { type:'file', data:Uint8Array }
    blocks: null,  // Map: "path:blockNo" -> Uint8Array (LRU)
    blockBytes: 0, // bytes held in blocks (Map insertion order = LRU order)
    seed: null,    // Map: lowercased path -> Uint8Array, from the startup pack
    packBytes: 0,  // startup pack size (stays alive while any seeded view is)
    smallBytes: 0, // small files fetched whole, held in smallLru
    smallLru: null, // Map: node -> bytes, oldest first (Map keeps insertion order)

    isNode: function () {
        return typeof ENVIRONMENT_IS_NODE !== 'undefined' && ENVIRONMENT_IS_NODE;
    },

    // ---- data access ------------------------------------------------------

    // I/O accounting for the probes: where load time goes.
    io: { requests: 0, bytes: 0, xhrMs: 0, convertMs: 0 },

    // ---- fast transport: worker fetch -> SharedArrayBuffer ----------------
    // Sync XHR on the main thread can only return text: Chrome decodes every
    // response into a UTF-16 string that we then walk byte by byte (~85Mb/s,
    // ~55s of a Zaton load). With cross-origin isolation a worker can fetch
    // binary data into shared memory while the main thread spins on a flag
    // (Atomics.wait is not allowed there, a spin is). The worker also reads
    // the next block of a file ahead, since archives are read mostly in order.
    // ctrl: [0] state 0=pending 1=done 2=error, [1] length, [2] HTTP status.
    sab: null,

    sabWorkerSource: function () {
        return 'var ctrl, data, ahead = new Map();\n' +
        'function get(url, start, end) {\n' +
        '  var key = url + "|" + start + "|" + end;\n' +
        '  var p = ahead.get(key);\n' +
        '  if (p) { ahead.delete(key); return p; }\n' +
        '  var h = end === undefined ? {} : { Range: "bytes=" + start + "-" + end };\n' +
        '  return fetch(url, { headers: h, cache: "no-store" }).then(function (r) {\n' +
        '    if (!r.ok) return { status: r.status };\n' +
        '    return r.arrayBuffer().then(function (b) { return { status: r.status, buf: b }; });\n' +
        '  });\n' +
        '}\n' +
        'onmessage = function (e) {\n' +
        '  var m = e.data;\n' +
        '  if (m.init) { ctrl = new Int32Array(m.ctrl); data = new Uint8Array(m.data); postMessage({ ready: true }); return; }\n' +
        '  get(m.url, m.start, m.end).then(function (res) {\n' +
        '    if (!res.buf || res.buf.byteLength > data.length) {\n' +
        '      Atomics.store(ctrl, 2, res.status); Atomics.store(ctrl, 1, res.buf ? res.buf.byteLength : 0);\n' +
        '      Atomics.store(ctrl, 0, 2); return;\n' +
        '    }\n' +
        '    data.set(new Uint8Array(res.buf));\n' +
        '    Atomics.store(ctrl, 1, res.buf.byteLength); Atomics.store(ctrl, 2, res.status);\n' +
        '    Atomics.store(ctrl, 0, 1);\n' +
        '    if (ahead.size >= 4) ahead.delete(ahead.keys().next().value);\n' +
        '    if (m.nextStart !== undefined)\n' +
        '      ahead.set(m.url + "|" + m.nextStart + "|" + m.nextEnd, get(m.url, m.nextStart, m.nextEnd));\n' +
        '  }, function () { Atomics.store(ctrl, 2, 0); Atomics.store(ctrl, 0, 2); });\n' +
        '};\n';
    },

    sabInit: function () {
        if (XRFS.isNode() || !globalThis.crossOriginIsolated || typeof SharedArrayBuffer === 'undefined')
            return;
        try {
            var ctrl = new SharedArrayBuffer(16);
            var data = new SharedArrayBuffer(16 * 1024 * 1024);
            var url = URL.createObjectURL(new Blob([XRFS.sabWorkerSource()], { type: 'text/javascript' }));
            var w = new Worker(url);
            // A new worker only starts once the main thread returns to its
            // event loop: enable the transport (and let main() run) after it
            // reports ready, or the first spin would wait forever.
            addRunDependency('xrfs-sab');
            w.onmessage = function (e) {
                if (!e.data || !e.data.ready) return;
                XRFS.sab = { worker: w, ctrl: new Int32Array(ctrl), data: new Uint8Array(data) };
                console.log('XRFS: fast transport on (worker fetch + SharedArrayBuffer)');
                removeRunDependency('xrfs-sab');
            };
            w.postMessage({ init: true, ctrl: ctrl, data: data });
        } catch (e) {
            console.log('XRFS: fast transport unavailable (' + e.message + '), using sync XHR');
        }
    },

    // Returns null when the request does not fit the shared buffer (caller
    // falls back to XHR).
    sabRange: function (url, start, end, nextStart, nextEnd) {
        var s = XRFS.sab;
        if (end !== undefined && end - start + 1 > s.data.length) return null;
        var t0 = performance.now();
        Atomics.store(s.ctrl, 0, 0);
        s.worker.postMessage({ url: new URL(url, location.href).href, start: start, end: end,
            nextStart: nextStart, nextEnd: nextEnd });
        while (Atomics.load(s.ctrl, 0) === 0) { /* spin: Atomics.wait is banned on the main thread */ }
        var state = Atomics.load(s.ctrl, 0), len = Atomics.load(s.ctrl, 1), status = Atomics.load(s.ctrl, 2);
        if (state === 2) {
            if (len > s.data.length) return null; // whole-file response too big
            throw new Error('XRFS: GET ' + url + ' -> ' + status);
        }
        var u8 = s.data.slice(0, len); // copy out of shared memory
        var t1 = performance.now();
        XRFS.io.requests++;
        XRFS.io.bytes += len;
        XRFS.io.xhrMs += t1 - t0;
        var per = XRFS.io.perUrl || (XRFS.io.perUrl = new Map());
        var e = per.get(url) || { n: 0, bytes: 0 };
        e.n++; e.bytes += len;
        if (!XRFS.io.frameTop || len > XRFS.io.frameTop.bytes)
            XRFS.io.frameTop = { url: url, bytes: len };
        per.set(url, e);
        return u8;
    },

    xhrRange: function (url, start, end) {
        var t0 = performance.now();
        var xhr = new XMLHttpRequest();
        xhr.open('GET', url, false);
        if (end !== undefined) xhr.setRequestHeader('Range', 'bytes=' + start + '-' + end);
        // Sync XHR on the main thread forbids responseType != '' -- pull the
        // bytes through a binary string instead (classic charset trick).
        try { xhr.overrideMimeType('text/plain; charset=x-user-defined'); } catch (e) {}
        xhr.send(null);
        if (xhr.status !== 200 && xhr.status !== 206 && xhr.status !== 0)
            throw new Error('XRFS: GET ' + url + ' -> ' + xhr.status);
        var text = xhr.responseText;
        var t1 = performance.now();
        var u8 = new Uint8Array(text.length);
        for (var i = 0; i < text.length; i++) u8[i] = text.charCodeAt(i) & 0xff;
        var t2 = performance.now();
        XRFS.io.requests++;
        XRFS.io.bytes += u8.length;
        XRFS.io.xhrMs += t1 - t0;
        XRFS.io.convertMs += t2 - t1;
        var per = XRFS.io.perUrl || (XRFS.io.perUrl = new Map());
        var e = per.get(url) || { n: 0, bytes: 0 };
        e.n++; e.bytes += u8.length;
        if (!XRFS.io.frameTop || u8.length > XRFS.io.frameTop.bytes)
            XRFS.io.frameTop = { url: url, bytes: u8.length };
        per.set(url, e);
        return u8;
    },

    urlFor: function (path) {
        var cfg = XRFS.cfg;
        return cfg.baseUrl + path.split('/').map(encodeURIComponent).join('/');
    },

    // Read [start, end) of a file from the environment.
    readRange: function (path, start, end, aheadStart, aheadEnd) {
        if (XRFS.isNode()) {
            var fs = require('node:fs');
            var full = XRFS.cfg.baseDir + '/' + path;
            var fd = fs.openSync(full, 'r');
            try {
                var len = end - start;
                var buf = Buffer.allocUnsafe(len);
                var got = fs.readSync(fd, buf, 0, len, start);
                return new Uint8Array(buf.buffer, buf.byteOffset, got);
            } finally {
                fs.closeSync(fd);
            }
        }
        var data = null;
        if (XRFS.sab)
            data = XRFS.sabRange(XRFS.urlFor(path), start, end - 1,
                aheadStart, aheadEnd === undefined ? undefined : aheadEnd - 1);
        if (!data) data = XRFS.xhrRange(XRFS.urlFor(path), start, end - 1);
        if (data.length > end - start) data = data.subarray(0, end - start);
        return data;
    },

    loadIndex: function () {
        var cfg = XRFS.cfg;
        var text;
        if (XRFS.isNode()) {
            var fs = require('node:fs');
            text = fs.readFileSync(cfg.indexFile || cfg.baseDir + '/files.json', 'utf8');
        } else {
            text = new TextDecoder().decode(XRFS.xhrRange(cfg.indexUrl));
        }
        var raw = JSON.parse(text);

        var root = { dirs: {}, files: {} };
        raw.dirs.forEach(function (d) {
            XRFS.indexDir(root, d.toLowerCase().split('/'), d);
        });
        raw.files.forEach(function (e) {
            var parts = e[0].toLowerCase().split('/');
            var name = parts.pop();
            var dir = XRFS.ensureDir(root, parts);
            dir.files[name] = [e[0].substring(e[0].lastIndexOf('/') + 1), e[1], e[2]];
        });
        XRFS.index = root;
        XRFS.overlay = new Map();
        XRFS.blocks = new Map();
        XRFS.smallLru = new Map();
        XRFS.persistDirty = new Set();
        XRFS.blockBytes = 0;
        XRFS.seqWindows = new Map();
        XRFS.loadPack();
    },

    // Startup pack (make_index.py): every small file in one request, so the
    // thousands of tiny startup opens (.thm, .ltx, .s) don't pay a sync-XHR
    // round trip each. Entries are subarray views -- no copies until read.
    loadPack: function () {
        var cfg = XRFS.cfg;
        XRFS.seed = new Map();
        var data;
        try {
            if (XRFS.isNode()) {
                var fs = require('node:fs');
                var path = cfg.packFile || cfg.baseDir + '/pack.bin';
                if (!fs.existsSync(path)) return;
                data = new Uint8Array(fs.readFileSync(path));
            } else {
                data = XRFS.xhrRange(cfg.packUrl);
            }
        } catch (e) {
            console.log('XRFS: no startup pack (' + e.message + '), falling back to per-file requests');
            return;
        }
        var dv = new DataView(data.buffer, data.byteOffset, data.byteLength);
        var off = 0;
        try {
            if (dv.getUint32(off, true) !== 0x46505258) throw new Error('bad magic'); // 'XRPF'
            var version = dv.getUint32(off + 4, true);
            if (version !== 1) throw new Error('version ' + version);
            off += 8;
            var count = dv.getUint32(off, true); off += 4;
            for (var i = 0; i < count; i++) {
                var keyLen = dv.getUint32(off, true); off += 4;
                var size = dv.getUint32(off, true); off += 4;
                var key = '';
                for (var k = 0; k < keyLen; k++) key += String.fromCharCode(data[off + k]);
                off += keyLen;
                XRFS.seed.set(key, data.subarray(off, off + size));
                off += size;
            }
            XRFS.packBytes = data.byteLength;
            console.log('XRFS: startup pack seeded ' + count + ' files');
        } catch (e) {
            XRFS.seed = new Map();
            console.log('XRFS: startup pack unusable (' + e.message + ')');
        }
    },

    ensureDir: function (tree, parts) {
        for (var i = 0; i < parts.length; i++) {
            if (!tree.dirs[parts[i]]) tree.dirs[parts[i]] = [parts[i], { dirs: {}, files: {} }];
            tree = tree.dirs[parts[i]][1];
        }
        return tree;
    },

    indexDir: function (root, lowerParts, origPath) {
        var tree = XRFS.ensureDir(root, lowerParts.slice(0, -1));
        var name = lowerParts[lowerParts.length - 1];
        var orig = origPath.substring(origPath.lastIndexOf('/') + 1);
        if (!tree.dirs[name]) tree.dirs[name] = [orig, { dirs: {}, files: {} }];
    },

    // Resolve a directory node's children lazily: index tree + overlay.
    resolveChild: function (node, name) {
        var path = XRFS.nodePath(node) + name;
        var ov = XRFS.overlay.get(path.toLowerCase());
        if (ov) return { overlay: ov, path: path };

        var tree = node.xrTree;
        if (tree) {
            var f = tree.files[name.toLowerCase()];
            if (f) return { file: f, path: path };
            var d = tree.dirs[name.toLowerCase()];
            if (d) return { dir: d, path: path };
        }
        return null;
    },

    nodePath: function (node) {
        var parts = [];
        for (var n = node; n && n.name !== '/'; n = n.parent) parts.unshift(n.name);
        return parts.length ? parts.join('/') + '/' : '';
    },

    // ---- block cache for large files --------------------------------------

    blockGet: function (path, blockNo) {
        var key = path + ':' + blockNo;
        var b = XRFS.blocks.get(key);
        if (b) { // refresh LRU position
            XRFS.blocks.delete(key);
            XRFS.blocks.set(key, b);
        }
        return b;
    },

    blockPut: function (path, blockNo, b) {
        var key = path + ':' + blockNo;
        var old = XRFS.blocks.get(key);
        if (old) { XRFS.blockBytes -= old.length; XRFS.blocks.delete(key); }
        XRFS.blocks.set(key, b);
        XRFS.blockBytes += b.length;
        var it = XRFS.blocks.keys();
        while (XRFS.blockBytes > XRFS.cfg.blockCacheBytes && XRFS.blocks.size > 1) {
            var k = it.next().value;
            XRFS.blockBytes -= XRFS.blocks.get(k).length;
            XRFS.blocks.delete(k);
        }
    },

    // Miss-fetch size per file: starts at minFetchBytes and doubles (up to
    // maxSeqFetchBytes) while misses keep landing just ahead of the previous
    // one -- e.g. an NPC's voice set, ~100 small oggs stored back to back in
    // an archive, all loaded during its spawn. A random miss resets it, so
    // scattered tiny reads (.thm at startup) stay cheap.
    seqWindows: null, // path -> { next: byte offset after the last fetch, size }
    fetchWindow: function (path, position) {
        var w = XRFS.seqWindows.get(path);
        var min = XRFS.cfg.minFetchBytes, max = XRFS.cfg.maxSeqFetchBytes;
        if (w && position >= w.next - min && position <= w.next + max)
            w.size = Math.min(w.size * 2, max);
        else
            w = { next: 0, size: min };
        w.next = position + w.size;
        XRFS.seqWindows.set(path, w);
        return w.size;
    },

    // Fetch blocks [b0, b1] of a file in one request and cache them; hint the
    // worker to read the same amount right after (sequential reads).
    fetchBlocks: function (path, size, b0, b1) {
        var bs = XRFS.cfg.blockSize;
        var start = b0 * bs, end = Math.min((b1 + 1) * bs, size);
        var aheadEnd = Math.min(end + (end - start), size);
        var data = XRFS.readRange(path, start, end, end < size ? end : undefined, end < size ? aheadEnd : undefined);
        for (var b = b0; b <= b1; b++) {
            var off = (b - b0) * bs;
            if (off >= data.length) break;
            // slice: a subarray would keep the whole fetch alive
            XRFS.blockPut(path, b, data.slice(off, Math.min(off + bs, data.length)));
        }
    },

    readIndexBytes: function (node, dst, offset, position, length) {
        var path = node.xrPath, size = node.size;
        if (size <= XRFS.cfg.smallFileLimit) {
            if (!node.xrData) {
                var seeded = XRFS.seed && XRFS.seed.get(path.toLowerCase());
                if (seeded) {
                    node.xrData = seeded;
                    XRFS.seed.delete(path.toLowerCase()); // the view keeps the pack alive
                } else {
                    node.xrData = XRFS.readRange(path, 0, size);
                    XRFS.smallTrack(node);
                }
                node.size = node.xrData.length; // trust the server/pack over the index
                if (node.xrData.length !== size)
                    console.log('XRFS WARNING: ' + path + ' index size ' + size +
                        ' != actual ' + node.xrData.length +
                        ' -- regenerate files.json and pack.bin together, deploy both');
            }
            if (XRFS.smallLru.has(node)) { // refresh LRU position
                XRFS.smallLru.delete(node);
                XRFS.smallLru.set(node, node.xrData.length);
            }
            var n = Math.min(length, node.xrData.length - position);
            if (n <= 0) return 0;
            dst.set(node.xrData.subarray(position, position + n), offset);
            return n;
        }
        var bs = XRFS.cfg.blockSize;
        length = Math.min(length, size - position);
        if (length <= 0) return 0;
        var maxRun = Math.max(1, Math.floor(XRFS.cfg.maxFetchBytes / bs));
        var done = 0;
        while (done < length) {
            var blockNo = Math.floor(position / bs);
            var inBlock = position % bs;
            var b = XRFS.blockGet(path, blockNo);
            if (!b) {
                // coalesce the missing blocks this read still needs
                var lastNeeded = Math.floor((position + (length - done) - 1) / bs);
                lastNeeded = Math.max(lastNeeded, blockNo + Math.floor(XRFS.fetchWindow(path, position) / bs) - 1);
                lastNeeded = Math.min(lastNeeded, Math.floor((size - 1) / bs));
                var b1 = blockNo;
                while (b1 < lastNeeded && b1 - blockNo + 1 < maxRun && !XRFS.blocks.has(path + ':' + (b1 + 1)))
                    b1++;
                XRFS.fetchBlocks(path, size, blockNo, b1);
                b = XRFS.blockGet(path, blockNo);
                if (!b) break;
            }
            var take = Math.min(length - done, bs - inBlock, b.length - inBlock);
            if (take <= 0) break;
            dst.set(b.subarray(inBlock, inBlock + take), offset + done);
            position += take; done += take;
        }
        return done;
    },

    // ---- FS interface -----------------------------------------------------

    mount: function (mount) {
        XRFS.loadIndex();
        var root = XRFS.createNode(null, '/', XRFS.DIR_MODE, 0);
        root.xrTree = XRFS.index;
        return root;
    },

    createNode: function (parent, name, mode, entry) {
        var node = FS.createNode(parent, name, mode);
        node.node_ops = XRFS.node_ops;
        node.stream_ops = XRFS.stream_ops;
        var now = Date.now();
        node.atime = node.mtime = node.ctime = now;
        if (mode === XRFS.FILE_MODE) {
            node.size = entry ? entry[1] : 0;
            node.xrEntry = entry || null;   // [origName, size, mtime]
            node.xrData = null;             // loaded cache for small files
            node.xrMem = null;              // overlay storage once written
            if (entry) node.mtime = node.atime = node.ctime = entry[2] * 1000;
        } else {
            node.size = 4096;
            node.contents = {}; // FSNode leaves this null; readdir/lookup need it
        }
        if (parent) parent.contents[name] = node;
        return node;
    },

    node_ops: {
        getattr: function (node) {
            return {
                dev: 1, ino: node.id, mode: node.mode, nlink: 1,
                uid: 0, gid: 0, rdev: 0, size: node.size,
                atime: new Date(node.atime), mtime: new Date(node.mtime), ctime: new Date(node.ctime),
                blksize: 4096, blocks: Math.ceil(node.size / 4096),
            };
        },
        setattr: function (node, attr) {
            ['mode', 'atime', 'mtime', 'ctime'].forEach(function (k) {
                if (attr[k] != null) node[k] = attr[k];
            });
            if (attr.size != null) {
                XRFS.resizeMem(node, attr.size);
                node.size = attr.size;
            }
        },
        lookup: function (parent, name) {
            if (!XRFS.nodeIsOurs(parent)) throw new FS.ErrnoError(XRFS.E.ENOENT);
            var hit = XRFS.resolveChild(parent, name);
            if (!hit) throw new FS.ErrnoError(XRFS.E.ENOENT);
            if (hit.overlay) {
                if (hit.overlay.type === 'dir')
                    return XRFS.createNode(parent, hit.overlay.origName || name, XRFS.DIR_MODE);
                var n = XRFS.createNode(parent, hit.overlay.origName || name, XRFS.FILE_MODE);
                n.xrMem = hit.overlay.data;
                n.size = hit.overlay.data.length;
                return n;
            }
            if (hit.dir) {
                var d = XRFS.createNode(parent, hit.dir[0], XRFS.DIR_MODE);
                d.xrTree = hit.dir[1];
                return d;
            }
            var f = XRFS.createNode(parent, hit.file[0], XRFS.FILE_MODE, hit.file);
            // Path for actual reads: rebuilt from on-disk casing (the engine
            // may ask for a lowercased name on a case-sensitive layout).
            f.xrPath = XRFS.nodePath(parent) + hit.file[0];
            return f;
        },
        mknod: function (parent, name, mode, dev) {
            if (!XRFS.nodeIsOurs(parent)) throw new FS.ErrnoError(XRFS.E.EPERM);
            var path = XRFS.nodePath(parent) + name;
            if (XRFS.resolveChild(parent, name)) throw new FS.ErrnoError(XRFS.E.EEXIST);
            var node;
            if ((mode & 0xF000) === 0x4000) {
                XRFS.overlay.set(path.toLowerCase(), { type: 'dir', origName: name });
                XRFS.persistMark(path);
                node = XRFS.createNode(parent, name, XRFS.DIR_MODE);
            } else {
                var data = new Uint8Array(0);
                XRFS.overlay.set(path.toLowerCase(), { type: 'file', data: data, origName: name });
                XRFS.persistMark(path);
                node = XRFS.createNode(parent, name, XRFS.FILE_MODE);
                node.xrMem = data;
            }
            return node;
        },
        rename: function (oldNode, newDir, newName) {
            if (!XRFS.nodeIsOurs(oldNode) || !XRFS.nodeIsOurs(newDir)) throw new FS.ErrnoError(XRFS.E.EPERM);
            var oldPath = XRFS.fullPath(oldNode);
            var newPath = XRFS.nodePath(newDir) + newName;
            var lower = oldPath.toLowerCase();
            var ov = XRFS.overlay.get(lower);
            if (ov) {
                XRFS.overlay.delete(lower);
                ov.origName = newName;
                XRFS.overlay.set(newPath.toLowerCase(), ov);
            } else {
                // Copy-on-rename from the index (used for log backups).
                var data = XRFS.readRange(oldPath, 0, oldNode.size);
                XRFS.overlay.set(newPath.toLowerCase(), { type: 'file', data: data, origName: newName });
                XRFS.overlay.set(lower, { type: 'gone' });
            }
            XRFS.cacheDrop(oldPath);
            XRFS.persistMark(oldPath);
            XRFS.persistMark(newPath);
        },
        unlink: function (parent, name) {
            var path = XRFS.nodePath(parent) + name;
            XRFS.overlay.set(path.toLowerCase(), { type: 'gone' });
            XRFS.cacheDrop(path);
            XRFS.persistMark(path);
            delete parent.contents[name];
        },
        rmdir: function (parent, name) {
            var path = XRFS.nodePath(parent) + name;
            XRFS.overlay.set(path.toLowerCase(), { type: 'gone' });
            XRFS.persistMark(path);
            delete parent.contents[name];
        },
        readdir: function (node) {
            var entries = ['.', '..'];
            var seen = {};
            var lowerPath = XRFS.fullPath(node).toLowerCase();
            XRFS.overlay.forEach(function (v, p) {
                // direct children only: the parent of p must be this directory
                // (idx == -1 for entries of the mount root, whose path is '')
                var idx = p.lastIndexOf('/');
                if (p.substring(0, Math.max(idx, 0)) !== lowerPath) return;
                var nm = p.substring(idx + 1);
                if (!nm || seen[nm]) return;
                seen[nm] = 1; // a tombstone also hides the index entry below
                if (v.type !== 'gone') entries.push(v.origName || nm);
            });
            var tree = node.xrTree;
            if (tree) {
                Object.keys(tree.files).forEach(function (k) {
                    var nm = tree.files[k][0];
                    if (!seen[k]) { seen[k] = 1; entries.push(nm); }
                });
                Object.keys(tree.dirs).forEach(function (k) {
                    var nm = tree.dirs[k][0];
                    if (!seen[k]) { seen[k] = 1; entries.push(nm); }
                });
            }
            return entries;
        },
        symlink: function (parent, newName, oldPath) {
            throw new FS.ErrnoError(XRFS.E.EPERM);
        },
    },

    stream_ops: {
        read: function (stream, buffer, offset, length, position) {
            var node = stream.node;
            if (position >= node.size) return 0;
            length = Math.min(length, node.size - position);
            if (node.xrMem) {
                var n = Math.min(length, node.xrMem.length - position);
                buffer.set(node.xrMem.subarray(position, position + n), offset);
                return n;
            }
            return XRFS.readIndexBytes(node, buffer, offset, position, length);
        },
        write: function (stream, buffer, offset, length, position) {
            var node = stream.node;
            if (!node.xrMem) { // copy-on-write an index-backed file
                node.xrMem = new Uint8Array(node.size);
                if (node.size) XRFS.readIndexBytes(node, node.xrMem, 0, 0, node.size);
                var p = XRFS.fullPath(node);
                XRFS.overlay.set(p.toLowerCase(), { type: 'file', data: node.xrMem, origName: node.name });
            }
            var end = position + length;
            if (end > node.xrMem.length) XRFS.resizeMem(node, end);
            node.xrMem.set(buffer.subarray(offset, offset + length), position);
            node.size = node.xrMem.length;
            node.mtime = Date.now();
            XRFS.persistMark(XRFS.fullPath(node));
            return length;
        },
        llseek: function (stream, offset, whence) {
            var position = offset;
            if (whence === 1) position += stream.position;
            else if (whence === 2) {
                if (FS.isFile(stream.node.mode)) position += stream.node.size;
            }
            if (position < 0) throw new FS.ErrnoError(XRFS.E.EINVAL);
            return position;
        },
        mmap: function (stream, length, position, prot, flags) {
            // Archives are mmap'ed by CLocatorAPI. Back it with a plain
            // heap buffer filled through the normal read path.
            if (typeof mmapAlloc !== 'function') throw new FS.ErrnoError(XRFS.E.ENODEV);
            var ptr = mmapAlloc(length);
            if (!ptr) throw new FS.ErrnoError(XRFS.E.ENOMEM);
            var node = stream.node;
            var written = 0;
            var tmp = new Uint8Array(HEAPU8.buffer, ptr, length);
            // one read call: lets the block cache coalesce the region into a
            // few large fetches instead of one per 64Kb
            while (written < length) {
                var got = XRFS.stream_ops.read(stream, tmp, written, length - written, position + written);
                if (got <= 0) break;
                written += got;
            }
            return { ptr: ptr, allocated: true };
        },
    },

    // ---- helpers ----------------------------------------------------------

    fullPath: function (node) {
        var base = XRFS.nodePath(node);
        return base.substring(0, base.length - 1); // strip trailing '/'
    },

    nodeIsOurs: function (node) {
        return node.node_ops === XRFS.node_ops;
    },

    resizeMem: function (node, newSize) {
        if (!node.xrMem) node.xrMem = new Uint8Array(newSize);
        if (newSize !== node.xrMem.length) {
            var bigger = new Uint8Array(newSize);
            bigger.set(node.xrMem.subarray(0, Math.min(newSize, node.xrMem.length)));
            node.xrMem = bigger;
            var p = XRFS.fullPath(node);
            XRFS.overlay.set(p.toLowerCase(), { type: 'file', data: node.xrMem, origName: node.name });
            XRFS.persistMark(p);
        }
    },

    smallTrack: function (node) {
        XRFS.smallLru.set(node, node.xrData.length);
        XRFS.smallBytes += node.xrData.length;
        var it = XRFS.smallLru.keys();
        while (XRFS.smallBytes > XRFS.cfg.smallCacheBytes && XRFS.smallLru.size > 1) {
            var old = it.next().value;
            if (old === node) break;
            XRFS.smallBytes -= XRFS.smallLru.get(old);
            XRFS.smallLru.delete(old);
            old.xrData = null; // refetched on the next read
        }
    },

    // Dev: drop extra files into the layout through the overlay before the
    // engine scans it, e.g. { 'gamedata/scripts/web_smoke.script': 'web_smoke.script' }
    // (index.html ?lua=). Not persisted.
    injectFiles: function (files) {
        Object.keys(files).forEach(function (path) {
            try {
                var data = XRFS.isNode()
                    ? new Uint8Array(require('node:fs').readFileSync(files[path]))
                    : XRFS.xhrRange(files[path]);
                XRFS.overlay.set(path.toLowerCase(),
                    { type: 'file', data: data, origName: path.substring(path.lastIndexOf('/') + 1) });
                XRFS.statMisses.clear();
                console.log('XRFS: injected ' + path + ' (' + data.length + ' bytes)');
            } catch (e) {
                console.log('XRFS: inject ' + path + ' failed: ' + e.message);
            }
        });
    },

    // ---- persistence (IndexedDB) -------------------------------------------
    // The overlay is the only writable storage; entries under persistPrefix
    // are mirrored to IndexedDB shortly after they change and restored into
    // the overlay at preRun, before the engine looks at its app data.

    persistDirty: null, // Set of lowercased paths waiting for a flush
    persistTimer: 0,

    persistWanted: function (lower) {
        var cfg = XRFS.cfg;
        if (XRFS.isNode() || typeof indexedDB === 'undefined') return false;
        if (lower.indexOf(cfg.persistPrefix) !== 0) return false;
        return !cfg.persistSkip.some(function (pre) { return lower.indexOf(pre) === 0; });
    },

    persistMark: function (path) {
        var lower = path.toLowerCase();
        if (!XRFS.persistWanted(lower)) return;
        XRFS.persistDirty.add(lower);
        // Debounced: a save is many small writes; flush once they settle.
        clearTimeout(XRFS.persistTimer);
        XRFS.persistTimer = setTimeout(XRFS.persistFlush, 1000);
    },

    persistOpen: function (cb) {
        var req = indexedDB.open(XRFS.cfg.persistDb, 1);
        req.onupgradeneeded = function () { req.result.createObjectStore('files'); };
        req.onsuccess = function () { cb(req.result); };
        req.onerror = function () {
            console.log('XRFS: IndexedDB unavailable (' + req.error + '), app data is not persistent');
            cb(null);
        };
    },

    persistFlush: function () {
        if (!XRFS.persistDirty.size) return;
        var paths = Array.from(XRFS.persistDirty);
        XRFS.persistDirty.clear();
        XRFS.persistOpen(function (db) {
            if (!db) return;
            // strict: Chrome's default (relaxed) may drop the last save if the
            // tab dies right after it
            var tx = db.transaction('files', 'readwrite', { durability: 'strict' });
            var store = tx.objectStore('files');
            paths.forEach(function (lower) {
                var ov = XRFS.overlay.get(lower);
                if (!ov) store.delete(lower);
                // keep tombstones: the file may also exist in the index
                else if (ov.type === 'gone') store.put({ type: 'gone' }, lower);
                else if (ov.type === 'dir') store.put({ type: 'dir', origName: ov.origName }, lower);
                // slice(): the overlay buffer keeps growing in place
                else store.put({ type: 'file', origName: ov.origName, data: ov.data.slice() }, lower);
            });
            tx.oncomplete = function () {
                db.close();
                console.log('XRFS: persisted ' + paths.length + ' app data change(s)');
            };
            tx.onerror = function () { console.log('XRFS: persist failed: ' + tx.error); };
        });
    },

    persistRestore: function () {
        if (XRFS.isNode() || typeof indexedDB === 'undefined') return;
        addRunDependency('xrfs-persist');
        XRFS.persistOpen(function (db) {
            if (!db) { removeRunDependency('xrfs-persist'); return; }
            var store = db.transaction('files', 'readwrite').objectStore('files');
            var count = 0, dropped = 0;
            store.openCursor().onsuccess = function (e) {
                var cur = e.target.result;
                if (cur) {
                    if (XRFS.persistWanted(cur.key)) {
                        XRFS.overlay.set(cur.key, cur.value);
                        count++;
                    } else {
                        cur.delete(); // stored by an older build (e.g. 140Mb cdb caches)
                        dropped++;
                    }
                    cur.continue();
                    return;
                }
                if (dropped) console.log('XRFS: dropped ' + dropped + ' stale app data entries from IndexedDB');
                db.close();
                if (count) console.log('XRFS: restored ' + count + ' app data entries from IndexedDB');
                XRFS.statMisses.clear();
                removeRunDependency('xrfs-persist');
            };
        });
    },

    // OpenAL (WebAudio) state for the probes: context state + playing sources.
    audioStats: function () {
        if (typeof AL === 'undefined' || !AL.currentCtx) return 'none';
        var ctx = AL.currentCtx, playing = 0, total = 0;
        for (var id in ctx.sources) {
            total++;
            if (ctx.sources[id].state === 0x1012 /* AL_PLAYING */) playing++;
        }
        return ctx.audioCtx.state + ' ' + playing + '/' + total;
    },

    // Dev probe ?fsprof=1: time every XRFS node/stream op and the generic
    // Emscripten FS entry points the engine's syscalls go through.
    prof: null,
    profileOps: function () {
        XRFS.prof = {};
        function wrap(obj, name, label) {
            var fn = obj[name];
            if (typeof fn !== 'function') return;
            var rec = XRFS.prof[label] = { n: 0, ms: 0 };
            obj[name] = function () {
                var t = performance.now();
                try { return fn.apply(this, arguments); }
                finally { rec.n++; rec.ms += performance.now() - t; }
            };
        }
        Object.keys(XRFS.node_ops).forEach(function (k) { wrap(XRFS.node_ops, k, 'node.' + k); });
        Object.keys(XRFS.stream_ops).forEach(function (k) { wrap(XRFS.stream_ops, k, 'stream.' + k); });
        ['lookupPath', 'open', 'close', 'stat', 'readdir', 'mmap', 'read', 'write', 'llseek']
            .forEach(function (k) { wrap(FS, k, 'FS.' + k); });
    },
    profTop: function () {
        var rows = Object.keys(XRFS.prof || {}).map(function (k) { return [k, XRFS.prof[k].n, XRFS.prof[k].ms]; });
        rows.sort(function (a, b) { return b[2] - a[2]; });
        return rows.filter(function (r) { return r[1]; });
    },

    // Top-N URLs by bytes fetched (dev probe ?iotop=SEC).
    ioTop: function (n) {
        var rows = [];
        (XRFS.io.perUrl || new Map()).forEach(function (e, url) { rows.push([url, e.n, e.bytes]); });
        rows.sort(function (a, b) { return b[2] - a[2]; });
        return rows.slice(0, n || 20);
    },

    // Memory snapshot for dev probes (?mem= in index.html): the wasm heap
    // plus what XRFS holds on the JS side, both count against the tab.
    memStats: function () {
        var blockBytes = 0;
        XRFS.blocks.forEach(function (b) { blockBytes += b.length; });
        return {
            heap: HEAPU8.buffer.byteLength,
            mallocInUse: typeof _xr_web_malloc_in_use === 'function' ? _xr_web_malloc_in_use() : -1,
            mallocArena: typeof _xr_web_malloc_arena === 'function' ? _xr_web_malloc_arena() : -1,
            audio: XRFS.audioStats(),
            io: XRFS.io,
            pack: XRFS.packBytes,
            small: XRFS.smallBytes,
            blocks: blockBytes,
        };
    },

    // FS.stat misses are the common case: on case-sensitive systems the
    // engine stats every path it resolves before looking it up in its own
    // archive index, and a stalker's sound themes probe <prefix>0..N for each
    // variant (~40k misses per group of NPCs coming online). Each miss walks
    // Emscripten's lookupPath; remember misses until anything is created or
    // moved. Overlay entries added behind FS's back clear it too.
    statMisses: new Set(),
    statCacheInstall: function () {
        var misses = XRFS.statMisses, stat = FS.stat;
        FS.stat = function (path, dontFollow) {
            if (!dontFollow && misses.has(path))
                throw new FS.ErrnoError(XRFS.E.ENOENT);
            try {
                return stat.apply(this, arguments);
            } catch (e) {
                if (!dontFollow && e && e.errno === XRFS.E.ENOENT && misses.size < 200000)
                    misses.add(path);
                throw e;
            }
        };
        ['mknod', 'mkdir', 'rename', 'symlink', 'chdir', 'mount'].forEach(function (k) {
            var fn = FS[k];
            FS[k] = function () { misses.clear(); return fn.apply(this, arguments); };
        });
    },

    cacheDrop: function (path) {
        var prefix = path + ':', drop = [];
        XRFS.blocks.forEach(function (b, k) { if (k.indexOf(prefix) === 0) drop.push(k); });
        drop.forEach(function (k) { XRFS.blockBytes -= XRFS.blocks.get(k).length; XRFS.blocks.delete(k); });
    },

    setup: function () {
        var cfg = Object.assign({}, XRFS_CONFIG_DEFAULTS, globalThis.XRFS_CONFIG || {});
        if (XRFS.isNode() && !cfg.baseDir)
            throw new Error('XRFS: node needs XRFS_CONFIG.baseDir');
        XRFS.cfg = cfg;
        XRFS.sabInit();
        if (cfg.profile) XRFS.profileOps();
        XRFS.statCacheInstall();
        FS.mkdirTree(cfg.mountpoint);
        FS.mount(XRFS, {}, cfg.mountpoint);
        FS.chdir(cfg.mountpoint);
        XRFS.injectFiles(cfg.injectFiles || {});
        // Expose for dev probing (tools/web tests); harmless in production.
        Module.FS = FS;
        Module.XRFS = XRFS;
        console.log('XRFS: mounted game layout at ' + cfg.mountpoint);
    },
};

Module.preRun = Module.preRun || [];
Module.preRun.push(XRFS.setup);
Module.preRun.push(function () { XRFS.persistRestore(); });
